 * AC: @ui-workflows-view ac-1
 */
export function fetchWorkflowsStatic(): { items: Workflow[]; total: number } {
	const snapshot = getSnapshot();
	if (!snapshot) {
		return { items: [], total: 0 };
	}

	return {
		items: snapshot.workflows ?? [],
		total: (snapshot.workflows ?? []).length
	};
}

